import 'package:flutter/widgets.dart';

/// Standard, discoverable token identifiers generated by styled widgets.
///
/// Each token corresponds to an interactive or validation state produced by
/// widgets in `package:styled/src/widgets`:
/// - [hovered]: Produced by `StyledPressableBox` when hovered.
/// - [pressed]: Produced by `StyledPressableBox` when pressed.
/// - [focused]: Produced by `StyledPressableBox` and `StyledTextField` on focus.
/// - [disabled]: Produced by `StyledPressableBox` and `StyledTextField` when disabled.
/// - [error]: Produced by `StyledTextField` when an error message is present.
abstract final class StyledToken {
  static const String hovered = 'hovered';
  static const String pressed = 'pressed';
  static const String focused = 'focused';
  static const String disabled = 'disabled';
  static const String error = 'error';
}

/// Screen size breakpoints for responsive styling.
enum StyledScreen {
  mobile(650),
  tablet(1360),
  desktop(double.infinity);

  final double width;

  const StyledScreen(this.width);

  static ({Size size, StyledScreen screen}) fromContext(BuildContext context) {
    final size = MediaQuery.sizeOf(context);
    final width = size.width;
    if (width < mobile.width) {
      return (size: size, screen: StyledScreen.mobile);
    } else if (width < tablet.width) {
      return (size: size, screen: StyledScreen.tablet);
    } else {
      return (size: size, screen: StyledScreen.desktop);
    }
  }

  bool get isMobile => this == StyledScreen.mobile;
  bool get isTablet => this == StyledScreen.tablet;
  bool get isDesktop => this == StyledScreen.desktop;

  bool operator >(StyledScreen other) => width > other.width;
  bool operator <(StyledScreen other) => width < other.width;
  bool operator >=(StyledScreen other) => width >= other.width;
  bool operator <=(StyledScreen other) => width <= other.width;
}

/// Extension on [BuildContext] for ergonomic screen size and breakpoint inspection.
extension StyledScreenContextExtension on BuildContext {
  /// The current [StyledScreen] tier (mobile, tablet, or desktop).
  StyledScreen get screen => StyledScreen.fromContext(this).screen;

  /// The current viewport [Size] from [MediaQuery].
  Size get screenSize => MediaQuery.sizeOf(this);

  /// Whether the screen is currently in the mobile tier (<650px).
  bool get isMobile => screen.isMobile;

  /// Whether the screen is currently in the tablet tier.
  bool get isTablet => screen.isTablet;

  /// Whether the screen is currently in the desktop tier.
  bool get isDesktop => screen.isDesktop;
}
